package com.example.stats.repo;

import com.example.stats.dto.UsageSummaryDto;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.List;

@Repository
public class StatsRepositoryImpl implements StatsRepository {
    private static final Logger log = LoggerFactory.getLogger(StatsRepositoryImpl.class);
    private final JdbcTemplate jdbcTemplate;

    public StatsRepositoryImpl(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public List<UsageSummaryDto> getUsageSummaryLast7Days() throws DataAccessException {
        String sql = ""
            + "SELECT account_id, COUNT(*) AS total_requests, COUNT(DISTINCT user_id) AS active_users "
            + "FROM requests "
            + "WHERE created_at >= ? "
            + "GROUP BY account_id";

        Timestamp sevenDaysAgo = Timestamp.valueOf(LocalDateTime.now(ZoneOffset.UTC).minusDays(7));
        try {
            return jdbcTemplate.query(sql, new Object[]{sevenDaysAgo}, (rs, rowNum) -> mapRow(rs));
        } catch (DataAccessException ex) {
            log.error("Failed to query usage summary for last 7 days", ex);
            throw ex;
        }
    }

    private UsageSummaryDto mapRow(ResultSet rs) throws SQLException {
        return new UsageSummaryDto(
            rs.getString("account_id"),
            rs.getLong("total_requests"),
            rs.getLong("active_users")
        );
    }
}
