StatsRepositoryImplIntegrationTest.java (integration test verifies 7-day window with H2)
```java
package com.example.stats.repo;

import com.example.stats.dto.UsageSummaryDto;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.JdbcTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@JdbcTest
class StatsRepositoryImplIntegrationTest {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private StatsRepositoryImpl repo;

    @BeforeEach
    void setUp() {
        repo = new StatsRepositoryImpl(jdbcTemplate);
        jdbcTemplate.execute("CREATE TABLE IF NOT EXISTS requests (id INT AUTO_INCREMENT PRIMARY KEY, account_id VARCHAR(100), user_id VARCHAR(100), created_at TIMESTAMP)");
        jdbcTemplate.update("DELETE FROM requests");
    }

    @Test
    void excludesOlderThan7Days() {
        LocalDateTime now = LocalDateTime.now(ZoneOffset.UTC);
        // older than 7 days
        jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_old", "user1", Timestamp.valueOf(now.minusDays(8)));
        // within 7 days
        jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_recent", "user1", Timestamp.valueOf(now.minusDays(1)));
        jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_recent", "user2", Timestamp.valueOf(now.minusDays(2)));

        List<UsageSummaryDto> result = repo.getUsageSummaryLast7Days();

        assertThat(result).hasSize(1);
        UsageSummaryDto dto = result.get(0);
        assertThat(dto.getAccountId()).isEqualTo("acct_recent");
        assertThat(dto.getTotalRequests()).isEqualTo(2);
        assertThat(dto.getActiveUsers()).isEqualTo(2);
    }
}
