@Override
public List<UsageSummaryDto> getUsageSummaryLast7Days(String accountId, Integer maxRows) throws DataAccessException {
    String sql;
    Object[] params;
    Timestamp sevenDaysAgo = Timestamp.valueOf(LocalDateTime.now(ZoneOffset.UTC).minusDays(7));

    if (accountId != null) {
        sql = ""
            + "SELECT account_id, COUNT(*) AS total_requests, COUNT(DISTINCT user_id) AS active_users "
            + "FROM requests "
            + "WHERE created_at >= ? AND account_id = ? "
            + "GROUP BY account_id";
        params = new Object[]{sevenDaysAgo, accountId};
    } else {
        sql = ""
            + "SELECT account_id, COUNT(*) AS total_requests, COUNT(DISTINCT user_id) AS active_users "
            + "FROM requests "
            + "WHERE created_at >= ? "
            + "GROUP BY account_id "
            + "ORDER BY total_requests DESC "
            + "LIMIT ?";
        params = new Object[]{sevenDaysAgo, maxRows};
    }

    try {
        return jdbcTemplate.query(sql, params, (rs, rowNum) -> mapRow(rs));
    } catch (DataAccessException ex) {
        log.error("Failed to query usage summary for last 7 days (accountId={})", accountId, ex);
        throw ex;
    }
}
