@Test
void unfilteredResultsAreSortedByTotalRequestsDesc() {
    LocalDateTime now = LocalDateTime.now(ZoneOffset.UTC);
    // Create accounts with varying request counts within 7 days
    // acct_high: 5 requests, acct_mid: 3, acct_low: 1
    for (int i = 0; i < 5; i++) {
        jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_high", "u"+i, Timestamp.valueOf(now.minusDays(1)));
    }
    for (int i = 0; i < 3; i++) {
        jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_mid", "v"+i, Timestamp.valueOf(now.minusDays(2)));
    }
    jdbcTemplate.update("INSERT INTO requests(account_id,user_id,created_at) VALUES(?,?,?)", "acct_low", "w1", Timestamp.valueOf(now.minusDays(3)));

    List<UsageSummaryDto> result = repo.getUsageSummaryLast7Days(null, 50);

    assertThat(result).isNotEmpty();
    // Assert strictly non-increasing totalRequests
    long prev = Long.MAX_VALUE;
    for (UsageSummaryDto dto : result) {
        assertThat(dto.getTotalRequests()).isLessThanOrEqualTo(prev);
        prev = dto.getTotalRequests();
    }
    // Also ensure the top account is acct_high
    assertThat(result.get(0).getAccountId()).isEqualTo("acct_high");
}
